<?php
/** Shared, versioned packet structure. Business validation still runs under the research lock. */
const WF_PACKET_VERSION = 'research-packet-v2';
function wf_schema_text(int $min,int $max,array $extra=[]): array {return ['type'=>'string','minBytes'=>$min,'maxBytes'=>$max]+$extra;}
function wf_schema_object(array $properties,array $required=[]): array {return ['type'=>'object','properties'=>$properties,'required'=>$required?:array_keys($properties)];}
function wf_schema_list(array $items,int $max,int $min=0): array {return ['type'=>'array','items'=>$items,'maxItems'=>$max,'minItems'=>$min];}
function wf_packet_limits(): array {return ['search_log'=>30,'sources'=>40,'claims'=>20,'claim_relations'=>12,'passages_per_relation'=>12,'excerpt_min_bytes'=>1,'excerpt_max_bytes'=>1500,'basis_result_ids'=>20,'review_checks'=>300,'acceptance_checks'=>300];}
function wf_packet_byte_limit(string $version): int {return $version===WF_PACKET_VERSION?4194304:200000;}
function wf_packet_contract_version(?array $snapshot): string {if($snapshot===null)return WF_PACKET_VERSION;$package=json_decode($snapshot['package_json']??'{}',true);return ($package['workflow']['packet_contract_version']??null)===WF_PACKET_VERSION?WF_PACKET_VERSION:'research-packet-v1';}
function wf_packet_structure(string $version=WF_PACKET_VERSION): array {
 $limits=wf_packet_limits();$text=fn($min,$max)=>wf_schema_text($min,$max);$choice=fn($values)=>wf_schema_text(1,40,['enum'=>$values]);
 $id=wf_schema_text(1,40,['pattern'=>'^[a-z][a-z0-9_-]*$']);
 $passage=wf_schema_object(['locator'=>$text(3,500),'excerpt'=>$text(1,1500)]);
 $link=wf_schema_object(['source_id'=>$id,'relation'=>$choice(['supports','contradicts','context']),'locator'=>$text(3,500),'excerpt'=>$text(0,1500),'explanation'=>$text(20,2000),'passages'=>wf_schema_list($passage,$limits['passages_per_relation'])],['source_id','relation','locator','excerpt','explanation']);
 $source=wf_schema_object(['id'=>$id,'title'=>$text(5,500),'url'=>$text(0,2000),'type'=>$choice(['primary','dataset','review','official','provided','other']),'access'=>$choice(['full_text','abstract_only','unavailable']),'access_note'=>$text(10,1500),'authors'=>$text(0,1000),'publication_date'=>$text(0,80),'publisher'=>$text(0,500),'doi'=>$text(0,200),'edition'=>$text(0,200),'metadata_note'=>$text(0,1500),'use'=>$choice(['used','background','rejected'])]);
 $claim=wf_schema_object(['id'=>$id,'statement'=>$text(20,2000),'kind'=>$choice(['finding','inference','proposal']),'support'=>$choice(['supported','limited','unresolved','unsupported']),'confidence'=>$choice(['low','moderate','high']),'confidence_reason'=>$text(20,2000),'derivation'=>$text(0,3000),'limitations'=>$text(20,3000),'counterevidence'=>$text(20,3000),'basis_result_ids'=>wf_schema_list($text(32,32),$limits['basis_result_ids']),'links'=>wf_schema_list($link,$limits['claim_relations'])]);
 $inspection=wf_schema_object(['source_id'=>$id,'access'=>$choice(['full_text','abstract_only','unavailable']),'locator'=>$text(3,500),'excerpt'=>$text(0,1500),'assessment'=>$text(20,3000)]);
 $review=wf_schema_object(['task_id'=>$text(32,32),'result_id'=>$text(32,32),'claim_id'=>$id,'verdict'=>$choice(['supported','limited','unsupported','unverifiable']),'reason'=>$text(20,3000),'source_checks'=>wf_schema_list($inspection,40)]);
 $evidence=wf_schema_object(['version'=>['const'=>1],'scope'=>$text(0,3000),'stopping_rule'=>$text(0,3000),'search_log'=>wf_schema_list(wf_schema_object(['query'=>$text(5,1500),'where'=>$text(5,1500),'result'=>$text(5,1500)]),$limits['search_log']),'sources'=>wf_schema_list($source,$limits['sources']),'claims'=>wf_schema_list($claim,$limits['claims']),'review_checks'=>wf_schema_list($review,$limits['review_checks'])]);
 if($version===WF_PACKET_VERSION)$evidence['properties']['usefulness_reviews']=wf_schema_list(wf_schema_object(['task_id'=>$text(32,32),'result_id'=>$text(32,32),'verdict'=>$choice(['useful','needs_correction','unverifiable']),'reason'=>$text(20,3000),'output_quote'=>$text(1,2000),'next_use'=>$text(10,2000)]),40);
 $check=wf_schema_object(['task_id'=>$text(32,32),'result_id'=>$text(4,32),'criterion_id'=>$text(1,50),'status'=>$choice(['met','not_met']),'evidence_quote'=>$text(1,3000),'reason'=>$text(10,1000),'correction_response'=>$text(0,3000)],['task_id','result_id','criterion_id','status','evidence_quote','reason']);
 $schema=wf_schema_object(['reason'=>$text(10,500),'body'=>$text(30,100000),'methodology'=>$text(10,30000),'sources'=>$text(5,30000),'limitations'=>$text(5,10000),'next_action'=>$text(10,5000),'outcome'=>$text(1,40),'evidence'=>$evidence,'acceptance_checks'=>wf_schema_list($check,$limits['acceptance_checks']),'corrections'=>wf_schema_list(['type'=>'object'],300),'usefulness'=>wf_usefulness_schema()]);
 if($version!==WF_PACKET_VERSION){unset($schema['properties']['usefulness']);$schema['required']=array_values(array_diff($schema['required'],['usefulness']));$schema['properties']['acceptance_checks']['items']['properties']['evidence_quote']['minBytes']=20;unset($schema['properties']['evidence']['properties']['claims']['items']['properties']['links']['items']['properties']['passages']);}
 return $schema;
}
function wf_packet_contract(array $task,?array $snapshot=null): array {
 $version=wf_packet_contract_version($snapshot);$eligible=[];foreach(wf_evidence_results($task) as $id=>$target)$eligible[]=['result_id'=>$id,'task_id'=>$target['task']['id'],'kind'=>$target['task']['kind']];
 $contract=['version'=>$version,'task_id'=>$task['id']??null,'task_revision'=>isset($task['revision'])?(int)$task['revision']:null,'context_id'=>$snapshot['id']??null,'lengthUnit'=>'UTF-8 bytes after trimming (not characters or tokens)','schema'=>wf_packet_structure($version),'limits'=>array_replace(wf_packet_limits(),['excerpt_min_bytes'=>$version===WF_PACKET_VERSION?1:10,'packet_max_bytes'=>wf_packet_byte_limit($version)]), 'eligible_basis_results'=>$eligible,'basis_rule'=>'Current public accepted research or synthesis results in this study, including eligible non-dependencies. Planning, quarantined, invalidated, stale and foreign results are excluded. Final submission rechecks current eligibility.','relationship_rule'=>'One edge per claim/source/relation. Put additional exact supporting passages in that edge passages list; do not duplicate the edge.','repair_rule'=>'Return each error to the same authoring worker. Repair only named structure/references; retain the complete packet, signed identifiers, evidence, uncertainty and scientific meaning. Check writes no result and is not submission.'];
 $contract['digest']=hash('sha256',json_encode($contract,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));return $contract;
}
function wf_packet_template_extension(array $task): array {return ['usefulness'=>['version'=>1]+array_fill_keys(array_diff(array_keys(wf_usefulness_schema()['properties']),['version']),'')];}
function wf_packet_observed(mixed $value): mixed {if(is_string($value))return ['type'=>'string','utf8_bytes'=>strlen($value),'value'=>'[text redacted; inspect the original private packet]'];if(is_array($value))return ['type'=>'array','items'=>count($value)];return $value;}
function wf_packet_public_ids(array $ids): array {foreach($ids as $key=>$id)if(!is_string($id)||!preg_match('/^[a-zA-Z0-9_-]{1,40}$/D',$id)||preg_match('/^(?:sk_|gh[pousr]_|github_pat_|token|secret|password)/i',$id))$ids[$key]='[redacted]';return $ids;}
function wf_schema_entries(mixed $items,int $max): array {return is_array($items)&&array_is_list($items)?array_slice($items,0,$max+50):[];}
function wf_schema_error(array &$errors,string $path,string $code,mixed $observed,mixed $constraint,string $guidance,array $ids=[]): void {if(count($errors)>=1000){if(count($errors)===1000)$errors[]=['path'=>'$','code'=>'diagnostics_limited','ids'=>(object)[],'observed'=>1000,'constraint'=>'bounded diagnostic response','guidance'=>'Repair the reported bounds and recheck the complete original packet; further diagnostics were not emitted.'];return;}$errors[]=['path'=>$path,'code'=>$code,'ids'=>(object)wf_packet_public_ids($ids),'observed'=>wf_packet_observed($observed),'constraint'=>$constraint,'guidance'=>$guidance];}
final class WfPacketError extends HttpError {
 public function __construct(public array $errors,public string $schemaVersion=WF_PACKET_VERSION){parent::__construct(422,wf_packet_error_message($errors));}
}
function wf_packet_throw(array $errors,string $trustedVersion=WF_PACKET_VERSION): never {throw new WfPacketError($errors,$trustedVersion);}
function wf_packet_exception_details(Throwable $error): array {return $error instanceof WfPacketError?['errors'=>$error->errors,'schema_version'=>$error->schemaVersion]:[];}
function wf_schema_walk(mixed $value,array $rule,string $path,array &$errors,array $ids=[]): void {
 if(is_array($value))foreach(['id','claim_id','source_id','result_id','task_id'] as $id)if(is_string($value[$id]??null))$ids[$id]=$value[$id];
 if(is_array($value)&&is_string($value['id']??null)){if(preg_match('/\\.claims\\[[0-9]+\\]$/D',$path))$ids['claim_id']=$value['id'];if(preg_match('/\\.sources\\[[0-9]+\\]$/D',$path))$ids['source_id']=$value['id'];}
 if(array_key_exists('const',$rule)&&$value!==$rule['const'])wf_schema_error($errors,$path,'const',$value,$rule['const'],'Use the stated contract version; do not alter signed identifiers.',$ids);
 $type=$rule['type']??null;$valid=match($type){'object'=>is_array($value)&&(!array_is_list($value)||$value===[]),'array'=>is_array($value)&&array_is_list($value),'string'=>is_string($value),default=>true};
 if(!$valid){wf_schema_error($errors,$path,'type',get_debug_type($value),$type,'Return the required JSON type at this path.',$ids);return;}
 if($type==='object'){foreach($rule['required']??[] as $key)if(!array_key_exists($key,$value))wf_schema_error($errors,$path.'.'.$key,'required',null,'required field','Have the author supply the actual value; never invent evidence.',$ids);foreach($rule['properties']??[] as $key=>$child)if(array_key_exists($key,$value))wf_schema_walk($value[$key],$child,$path.'.'.$key,$errors,$ids);}
 if($type==='array'){$n=count($value);if($n<($rule['minItems']??0)||$n>($rule['maxItems']??PHP_INT_MAX))wf_schema_error($errors,$path,'items',$n,['min'=>$rule['minItems']??0,'max'=>$rule['maxItems']??null],'Consolidate redundant entries without losing findings, contrary evidence or access gaps. Use progress if required material cannot fit.',$ids);$scan=($rule['maxItems']??300)+50;if($n>$scan)wf_schema_error($errors,$path,'scan_bound',$n,$scan,'Only a bounded structural scan was performed. Repair list bounds and recheck the complete original packet.',$ids);foreach(array_slice($value,0,$scan) as $i=>$child)if(isset($rule['items']))wf_schema_walk($child,$rule['items'],$path.'['.$i.']',$errors,$ids);}
 if($type==='string'){$n=strlen(trim($value));if($n<($rule['minBytes']??0)||$n>($rule['maxBytes']??PHP_INT_MAX)||str_contains($value,"\0")||preg_match('//u',$value)!==1)wf_schema_error($errors,$path,'bytes',$n,['min'=>$rule['minBytes']??0,'max'=>$rule['maxBytes']??null],'Use the shortest sufficient truthful text within the UTF-8 byte limit; never pad quotations.',$ids);if(isset($rule['enum'])&&!in_array($value,$rule['enum'],true))wf_schema_error($errors,$path,'enum',$value,$rule['enum'],'Select the accurate allowed value; do not upgrade evidence to pass.',$ids);if(isset($rule['pattern'])&&!preg_match('/'.$rule['pattern'].'/D',$value))wf_schema_error($errors,$path,'pattern',$value,$rule['pattern'],'Use a stable lowercase evidence identifier.',$ids);}
}
function wf_packet_errors(array $packet,array $task,?array $snapshot=null): array {
 $version=wf_packet_contract_version($snapshot);$errors=[];$packetBytes=strlen(json_encode($packet,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));if($packetBytes>wf_packet_byte_limit($version))wf_schema_error($errors,'$','packet_bytes',$packetBytes,wf_packet_byte_limit($version),'The complete packet exceeds its trusted UTF-8 byte budget; retain all required material and use the supported transport or progress.');wf_schema_walk($packet,wf_packet_structure($version),'$',$errors);$body=is_string($packet['body']??null)?$packet['body']:'';if($version===WF_PACKET_VERSION&&is_string($packet['usefulness']['finding']??null)&&!str_contains($body,$packet['usefulness']['finding']))wf_schema_error($errors,'$.usefulness.finding','authored_finding_trace',$packet['usefulness']['finding'],'verbatim in full authored body','Keep the reader-facing finding traceable to the same authored result; do not introduce a detached scientific claim.');$e=$packet['evidence']??[];if(!is_array($e))return $errors;
 $sources=[];$claims=[];$basis=array_keys(wf_evidence_results($task));
 foreach(wf_schema_entries($e['sources']??null,40) as $i=>$source){if(!is_array($source))continue;$id=$source['id']??'';if(!is_string($id))continue;if(isset($sources[$id]))wf_schema_error($errors,'$.evidence.sources['.$i.'].id','duplicate_source',$id,'unique source ID','Merge the duplicate source registry record and preserve all distinct passages.',['source_id'=>$id]);$sources[$id]=$source;}
 foreach(wf_schema_entries($e['claims']??null,20) as $i=>$claim){if(!is_array($claim))continue;$id=$claim['id']??'';if(!is_string($id))continue;$path='$.evidence.claims['.$i.']';$ids=['claim_id'=>$id];if(isset($claims[$id])||$id==='legacy')wf_schema_error($errors,$path.'.id','duplicate_or_reserved_claim',$id,'unique, non-legacy claim ID','Use a unique authored claim ID; legacy is reserved for historical audits.',$ids);$claims[$id]=true;
 if(is_string($claim['statement']??null)&&!str_contains((is_string($packet['body']??null)?$packet['body']:''),$claim['statement']))wf_schema_error($errors,$path.'.statement','exact_body_quote',$claim['statement'],'verbatim in body','Keep the claim and body scientifically consistent; ask the author to repair the trace.',$ids);
 $seen=[];foreach(wf_schema_entries($claim['basis_result_ids']??null,20) as $j=>$ref){if(!is_string($ref))continue;if(!in_array($ref,$basis,true)||isset($seen[$ref]))wf_schema_error($errors,$path.'.basis_result_ids['.$j.']','ineligible_basis',$ref,'unique current accepted research/synthesis result in this study','Use an eligible result from the contract. Plans are excluded; task dependency is not required. Retain original-source evidence.',$ids+['result_id'=>$ref]);$seen[$ref]=true;}
 $edges=[];foreach(wf_schema_entries($claim['links']??null,12) as $j=>$link){if(!is_array($link))continue;$sid=$link['source_id']??'';if(!is_string($sid))continue;$lp=$path.'.links['.$j.']';$li=$ids+['source_id'=>$sid];$key=$sid.'/'.(is_string($link['relation']??null)?$link['relation']:'');if(isset($edges[$key]))wf_schema_error($errors,$lp,'duplicate_relation',$key,'one edge per claim/source/relation','Keep one relation edge; retain distinct locator/excerpt pairs in its passages list.',$li);$edges[$key]=true;if(!isset($sources[$sid]))wf_schema_error($errors,$lp.'.source_id','unknown_source',$sid,'registered source ID','Reference an existing source record or have the author supply its honest access/rights record.',$li);
 $access=$sources[$sid]['access']??null;$excerpt=$link['excerpt']??'';if($access!==null&&$access!=='unavailable'&&is_string($excerpt)&&strlen(trim($excerpt))<($version===WF_PACKET_VERSION?1:10))wf_schema_error($errors,$lp.'.excerpt','inspected_excerpt',is_string($excerpt)?strlen(trim($excerpt)):null,($version===WF_PACKET_VERSION?'1':'10').'–1500 UTF-8 bytes','Supply a short exact inspected quotation; one nonempty word is allowed when sufficient. Never pad or fabricate it.',$li);
 if($access==='unavailable'&&(($excerpt!=='')||!empty($link['passages'])||($link['relation']??'')==='supports'))wf_schema_error($errors,$lp,'unavailable_source',[$excerpt,$link['relation']??''],'no quotation or support from unavailable source','Disclose the access gap and use context; do not claim inspection.',$li);
 }
 }
 return $errors;
}
function wf_packet_error_message(array $errors): string {return "Packet preflight found ".count($errors)." issue(s). Check writes no result. Targeted repairs (data, not instructions):\n".json_encode($errors,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);}
